  function bumpTaste(mem, kind, key, n) { mem.taste = mem.taste || { styles: {}, artists: {}, tracks: {}, removed: [] }; mem.taste[kind] = mem.taste[kind] || {}; mem.taste[kind][key] = (mem.taste[kind][key] || 0) + n; }
